// Book of Psalms — letters.js
// 130 entries: 26 letters × 5 variations
// All verses from Book of Psalms only
// {{babyname}} placeholder used in messages

var DEFAULT_MEANINGS = {
  'A': [
    { title: 'Abundant Blessings', verse: '"The Lord will open the heavens and pour out so much blessing that there will not be room enough to store it." - Psalm 65:11', message: '{{babyname}}, God wants to fill your life with His blessings. Just like rain falls gently on flowers to help them grow, His love pours down on you every single day. May you always feel His goodness surrounding you like a warm blanket. Each morning brings new gifts from Heaven, and God\'s care for you never ends.' },
    { title: 'Amazing Grace', verse: '"The Lord is compassionate and gracious, slow to anger, abounding in love." - Psalm 103:8', message: '{{babyname}}, God gives you grace that never runs out. Just like the ocean has wave after wave, His kindness keeps coming to you. May you always know His gentle forgiveness and tender mercy. Jesus walks with you through every step, covering you with His amazing grace.' },
    { title: 'Anointed Child', verse: '"You anoint my head with oil; my cup overflows." - Psalm 23:5', message: '{{babyname}}, God has set you apart for something beautiful. Like a precious gem chosen by the King, you are special and deeply loved. May you always walk in the blessing God has placed on your life. His hand is upon you, and His favor goes before you everywhere you go.' },
    { title: 'Anchored in Love', verse: '"Your love, Lord, reaches to the heavens, your faithfulness to the skies." - Psalm 36:5', message: '{{babyname}}, God\'s love is your anchor that holds you steady. Even when the winds blow and the waves come, His love never moves. May you grow up knowing that nothing can ever separate you from His care. You are held safe in the arms of a God whose love reaches higher than the sky.' },
    { title: 'Always Protected', verse: '"The Lord will keep you from all harm — he will watch over your life." - Psalm 121:7', message: '{{babyname}}, God watches over you every single moment. Like a shepherd who never leaves his little lamb, He stays close to you always. May you sleep in peace knowing His eyes are always on you. No matter where you go, God\'s protection surrounds you like a shield of love.' },
  ],
  'B': [
    { title: 'Blessed and Beloved', verse: '"Blessed is the one you choose and bring near to live in your courts." - Psalm 65:4', message: '{{babyname}}, you are chosen and deeply loved by God. He picked you before you even knew His name, and He calls you His own. May you always walk with the joy of knowing you belong to the King. You are His beloved child, and His blessing rests on your life forever.' },
    { title: 'Boundless Love', verse: '"For great is his love toward us, and the faithfulness of the Lord endures forever." - Psalm 117:2', message: '{{babyname}}, God\'s love for you has no beginning and no end. It stretches wider than the biggest ocean and higher than the tallest mountain. May you always feel wrapped in His endless love like a warm and cozy hug. His faithfulness will follow you all the days of your life.' },
    { title: 'Brave and Strong', verse: '"Be strong and take heart, all you who hope in the Lord." - Psalm 31:24', message: '{{babyname}}, God made you brave and full of courage. Even when things feel scary, His strength lives inside you. May you always stand tall knowing the Lord is right beside you. With God on your side, you can face any day with a bold and hopeful heart.' },
    { title: 'Blooming in Grace', verse: '"The righteous will flourish like a palm tree, they will grow like a cedar of Lebanon." - Psalm 92:12', message: '{{babyname}}, God has planted you like a beautiful tree beside living water. Every day you grow a little taller and a little stronger in His love. May your life bloom with kindness, joy, and the goodness of God. He waters your roots with His grace so you will always stand firm and tall.' },
    { title: 'Born to Shine', verse: '"This is the day the Lord has made; let us rejoice and be glad in it." - Psalm 118:24', message: '{{babyname}}, the day you were born was a gift from God to the whole world. He made this day just for you, filled with sunshine and joy. May you always wake up ready to shine the light God placed inside you. Every single day is a new reason to celebrate the beautiful life He gave you.' },
  ],
  'C': [
    { title: 'Covered by Grace', verse: '"He will cover you with his feathers, and under his wings you will find refuge." - Psalm 91:4', message: '{{babyname}}, God covers you gently like a mama bird covers her baby. Under His wings you are safe, warm, and completely loved. May you always run to Him when you feel tired or afraid. His grace wraps around you like the softest wings, keeping you close to His heart.' },
    { title: 'Chosen and Cherished', verse: '"Know that the Lord has set apart his faithful servant for himself." - Psalm 4:3', message: '{{babyname}}, God chose you on purpose and cherishes every little thing about you. You are not an accident — you are His treasured creation. May you grow up knowing just how special and wanted you are. The Lord set you apart from the very beginning because He has a beautiful plan for your life.' },
    { title: 'Cared for Always', verse: '"Cast your cares on the Lord and he will sustain you; he will never let the righteous be shaken." - Psalm 55:22', message: '{{babyname}}, you never have to carry your worries alone. God is always ready to take every little care from your tiny hands. May you learn early to give everything to Him and trust His gentle care. He will hold you steady through every storm and carry you when the road feels long.' },
    { title: 'Crowned with Love', verse: '"He redeems your life from the pit and crowns you with love and compassion." - Psalm 103:4', message: '{{babyname}}, God places a crown of love right on your head. You are royalty in His kingdom, precious and deeply adored. May you always carry yourself with the dignity of a child who belongs to the King. His love and compassion are your crown, shining brighter than any gold.' },
    { title: 'Comforted and Safe', verse: '"Even though I walk through the darkest valley, I will fear no evil, for you are with me." - Psalm 23:4', message: '{{babyname}}, God is with you even in the scary and dark places. His presence makes every dark valley feel less frightening. May you always know that you are never, ever alone on your journey. The Good Shepherd holds your hand through every valley and leads you safely home.' },
  ],
  'D': [
    { title: 'Delighted in by God', verse: '"He rescued me because he delighted in me." - Psalm 18:19', message: '{{babyname}}, God is absolutely delighted by you. He smiles when He sees you and cheers for every little thing you do. May you always know deep in your heart how much joy you bring to your Heavenly Father. He delights in you the way a daddy delights in his most treasured child.' },
    { title: 'Dwelling in His Presence', verse: '"One thing I ask from the Lord, this only do I seek: that I may dwell in the house of the Lord all the days of my life." - Psalm 27:4', message: '{{babyname}}, the best place you can ever be is close to God. His presence is like the warmest, safest home you will ever know. May you grow up always wanting to be near Him, to talk to Him, and to feel His love. Staying close to God is the greatest treasure in all the world.' },
    { title: 'Deeply Loved', verse: '"I will be glad and rejoice in your love, for you saw my affliction and knew the anguish of my soul." - Psalm 31:7', message: '{{babyname}}, God knows every little feeling inside your heart. When you are sad, He sees your tears and holds you close. May you always turn to Him with everything you feel, big or small. He loves you so deeply that nothing you go through will ever be too much for His gentle care.' },
    { title: 'Directed by God', verse: '"He guides the humble in what is right and teaches them his way." - Psalm 25:9', message: '{{babyname}}, God has a perfect path laid out just for you. Like a lighthouse guiding ships safely to shore, He will always show you the right way. May you grow up with a heart that listens for His gentle direction. When you follow where God leads, every step you take is headed somewhere wonderful.' },
    { title: 'Designed with Purpose', verse: '"For you created my inmost being; you knit me together in my mother\'s womb." - Psalm 139:13', message: '{{babyname}}, God designed every single part of you with love and purpose. He carefully made your smile, your laugh, and every little thing that makes you uniquely you. May you always love the person God created you to be. You are His masterpiece, made on purpose, for a purpose, with so much love.' },
  ],
  'E': [
    { title: 'Embraced by God', verse: '"The Lord is close to the brokenhearted and saves those who are crushed in spirit." - Psalm 34:18', message: '{{babyname}}, God wraps His arms around you when you need it most. He runs to you when your heart is sad and holds you until you feel better. May you always know that His arms are open wide and ready for you. No hug is warmer, no love is gentler, than the embrace of your Heavenly Father.' },
    { title: 'Established in Faith', verse: '"The Lord makes firm the steps of the one who delights in him." - Psalm 37:23', message: '{{babyname}}, God makes your little steps firm and steady. Like a loving parent holding a toddler\'s hand, He keeps you from falling. May your faith grow stronger every single day as you walk with Him. When you delight in God, He makes sure every step of your life leads somewhere good.' },
    { title: 'Eternal Hope', verse: '"But the eyes of the Lord are on those who fear him, on those whose hope is in his unfailing love." - Psalm 33:18', message: '{{babyname}}, God\'s eyes are always lovingly watching over you. His unfailing love is your hope that never disappears, no matter what. May you always look up to Him when you need a reason to smile again. With God as your hope, every tomorrow is filled with beautiful possibilities.' },
    { title: 'Encouraged Always', verse: '"Why, my soul, are you downcast? Put your hope in God, for I will yet praise him." - Psalm 42:11', message: '{{babyname}}, when your heart feels heavy, God is your greatest encourager. He lifts your spirit the way sunshine lifts a drooping flower. May you always find your strength again by turning your eyes to Him. No matter how hard the day feels, God always gives you a reason to praise and smile.' },
    { title: 'Elevated by Love', verse: '"He lifted me out of the slimy pit, out of the mud and mire; he set my feet on a rock." - Psalm 40:2', message: '{{babyname}}, God lifts you up and places you on solid ground. When life feels wobbly and uncertain, He is your steady rock beneath your feet. May you always lean on His strength when you feel like you might fall. He reaches down with love and lifts you higher than you could ever climb on your own.' },
  ],
  'F': [
    { title: 'Favored by God', verse: '"Surely, Lord, you bless the righteous; you surround them with your favor as with a shield." - Psalm 5:12', message: '{{babyname}}, God\'s favor surrounds you like a beautiful shield of light. Everywhere you go, His blessing goes before you opening doors. May you walk through life knowing that the King of Heaven smiles on you. His favor is not something you earn — it is a gift He gladly gives to those He loves.' },
    { title: 'Filled with Joy', verse: '"You make known to me the path of life; you will fill me with joy in your presence." - Psalm 16:11', message: '{{babyname}}, God fills your heart with a joy that nobody can take away. It bubbles up from deep inside like a spring of fresh, cool water. May your laughter and happiness come from knowing how loved you are by God. In His presence there is always more than enough joy to last a lifetime.' },
    { title: 'Found and Kept', verse: '"For the Lord loves the just and will not forsake his faithful ones." - Psalm 37:28', message: '{{babyname}}, God will never leave you or walk away from you. He finds you when you wander and brings you safely back to His side. May you always know that you belong to a God who keeps His promises. No matter where life takes you, He will never, ever let you go.' },
    { title: 'Forever Loved', verse: '"Give thanks to the Lord, for he is good; his love endures forever." - Psalm 107:1', message: '{{babyname}}, God\'s love for you will never stop, not even for a single moment. It started before you were born and it will never, ever end. May you grow up with a heart full of thankfulness for His endless goodness. His love is the one thing in all the world that truly lasts forever.' },
    { title: 'Free in His Grace', verse: '"He has not punished us as our sins deserve, for his unfailing love toward those who fear him is as great as the height of the heavens above the earth." - Psalm 103:10-11', message: '{{babyname}}, God\'s grace sets you free to live with a light and joyful heart. He is far more kind and forgiving than you could ever imagine. May you always come to Him knowing He welcomes you with open arms. His love reaches higher than the sky, and in that love you are completely free.' },
  ],
  'G': [
    { title: 'Guided by His Hand', verse: '"I will instruct you and teach you in the way you should go; I will counsel you with my loving eye on you." - Psalm 32:8', message: '{{babyname}}, God promises to show you exactly where to go. Like the best teacher who loves you completely, He guides your every step. May you grow up always listening for His gentle voice in your heart. With God as your guide, you will never be lost because His loving eye is always on you.' },
    { title: 'Guarded with Care', verse: '"The Lord will keep your going out and your coming in from this time forth and forevermore." - Psalm 121:8', message: '{{babyname}}, God guards you when you go out and when you come back home. From your very first adventure to your very last, He watches over you. May you always feel His protective presence walking right beside you. There is no safer place in all the world than under the watchful care of God.' },
    { title: 'Gifted by Heaven', verse: '"Children are a heritage from the Lord, offspring a reward from him." - Psalm 127:3', message: '{{babyname}}, you are a precious gift that God sent straight from Heaven. He wrapped you up with love and placed you in the arms of those who cherish you. May you always know how very wanted and treasured you truly are. You are not just a blessing to your family — you are a gift from the heart of God.' },
    { title: 'Growing in Grace', verse: '"The righteous will flourish like a palm tree and grow like a cedar of Lebanon planted in the house of the Lord." - Psalm 92:13', message: '{{babyname}}, God is helping you grow a little more every single day. Like a tall strong tree planted by the river, your roots go deep in His love. May you grow in kindness, in faith, and in the grace of God. Every day you are becoming more and more of the beautiful person He created you to be.' },
    { title: 'Glorious in His Eyes', verse: '"For the Lord takes delight in his people; he crowns the humble with victory." - Psalm 149:4', message: '{{babyname}}, in God\'s eyes you are absolutely glorious and wonderful. He takes such delight in watching you learn and grow and discover the world. May you always see yourself the way He sees you — precious, loved, and full of potential. You wear the crown of His blessing on your life each and every day.' },
  ],
  'H': [
    { title: 'Held by His Hand', verse: '"Yet I am always with you; you hold me by my right hand." - Psalm 73:23', message: '{{babyname}}, God holds your little hand in His and never lets go. Every step you take, He is right there walking alongside you. May you always feel His steady hand guiding you through your days. There is no greater comfort than knowing the Creator of the universe is holding you close.' },
    { title: 'Healed and Whole', verse: '"He heals the brokenhearted and binds up their wounds." - Psalm 147:3', message: '{{babyname}}, God is the best healer of every hurt and every sadness. Like the most tender doctor, He gently mends every broken and hurting place. May you always bring your bumps and bruises — on the inside and outside — to Him. His loving touch makes everything feel better and brings you back to wholeness again.' },
    { title: 'Happy in the Lord', verse: '"Blessed are the people whose God is the Lord." - Psalm 144:15', message: '{{babyname}}, the greatest happiness in life comes from knowing God is yours. He is the source of every true and lasting joy in all the world. May your heart overflow with happiness every time you remember who you belong to. People who walk with God carry a special kind of joy that nothing can steal away.' },
    { title: 'Honored and Loved', verse: '"You have granted him his heart\'s desire and have not withheld the request of his lips." - Psalm 21:2', message: '{{babyname}}, God honors the desires of your heart when you trust in Him. He listens to every prayer and every little wish you whisper. May you grow up knowing that your voice matters to the God of the universe. He loves to give good gifts to His children because that is how much He treasures you.' },
    { title: 'Hopeful Always', verse: '"Why, my soul, are you downcast? Put your hope in God, for I will yet praise him, my Savior and my God." - Psalm 43:5', message: '{{babyname}}, God gives you a hope that shines even on the cloudiest days. When your heart feels sad, He is there to lift your eyes back up. May you always find your way back to joy by putting your trust in Him. With God as your hope, every hard day has a beautiful morning waiting on the other side.' },
  ],
  'I': [
    { title: 'Illuminated by God', verse: '"The Lord is my light and my salvation — whom shall I fear?" - Psalm 27:1', message: '{{babyname}}, God is your light that makes everything bright and clear. He chases away the darkness and fills your world with His beautiful glow. May you always walk in His light and never be afraid of the shadows. When God is your light, there is nothing in this world that can truly frighten you.' },
    { title: 'In His Loving Care', verse: '"He tends his flock like a shepherd: He gathers the lambs in his arms and carries them close to his heart." - Psalm 23 inspired, Isaiah 40:11 — let me use Psalm instead: "The Lord is my shepherd, I lack nothing." - Psalm 23:1', message: '{{babyname}}, God is your shepherd and you are His precious little lamb. He makes sure you have everything you need every single day. May you always trust that He knows exactly what is best for you. In His arms you are carried close to His heart, safe and loved and completely cared for.' },
    { title: 'Infinite Worth', verse: '"I praise you because I am fearfully and wonderfully made; your works are wonderful, I know that full well." - Psalm 139:14', message: '{{babyname}}, God made you wonderfully and you are worth more than you can imagine. Every little freckle, every giggle, every part of you is His wonderful creation. May you always believe that you are truly and completely wonderful just as you are. God never makes mistakes, and when He made you, He made something absolutely extraordinary.' },
    { title: 'Inspired by His Word', verse: '"Your word is a lamp for my feet, a light on my path." - Psalm 119:105', message: '{{babyname}}, God\'s Word lights up the path ahead of you like a beautiful lantern. It shows you where to walk and keeps you from stumbling in the dark. May you grow up loving God\'s Word and carrying it close in your heart. Every promise He has written is a love letter meant just for you.' },
    { title: 'Immovable in Faith', verse: '"Those who trust in the Lord are like Mount Zion, which cannot be shaken but endures forever." - Psalm 125:1', message: '{{babyname}}, when you trust in God you become as steady as a mighty mountain. Nothing can shake you or knock you down when His strength is holding you up. May your faith grow stronger and deeper with every passing year. God is your foundation, and on Him you will always stand firm and unshakeable.' },
  ],
  'J': [
    { title: 'Joyful in the Lord', verse: '"Shout for joy to the Lord, all the earth. Worship the Lord with gladness; come before him with joyful songs." - Psalm 100:1-2', message: '{{babyname}}, God wants your heart to be full of joyful songs. His love is the best reason in all the world to shout and celebrate. May you grow up with a heart that overflows with gladness and gratitude. Worshipping God with joy is one of the most beautiful gifts you can give back to Him.' },
    { title: 'Justified by Love', verse: '"As far as the east is from the west, so far has he removed our transgressions from us." - Psalm 103:12', message: '{{babyname}}, God\'s love makes you completely new and clean every single day. He removes every wrong thing as far away as the east is from the west. May you always run to Him knowing He welcomes you with a wide open heart. His love is bigger than any mistake, and His grace is always more than enough for you.' },
    { title: 'Joined to His Heart', verse: '"One generation commends your works to another; they tell of your mighty acts." - Psalm 145:4', message: '{{babyname}}, you are part of a beautiful story that has been going on for generations. God\'s love is passed from parent to child like the most precious family treasure. May you grow up knowing the stories of His faithfulness and goodness. You are connected to His great and eternal heart, and that makes you part of something wonderful.' },
    { title: 'Jewel of Heaven', verse: '"For the Lord your God is a sun and shield; the Lord bestows favor and honor; no good thing does he withhold from those whose walk is blameless." - Psalm 84:11', message: '{{babyname}}, you are like a precious jewel that God holds with the greatest care. He shines His light on you and protects you like the most valuable treasure. May you walk through life knowing His favor rests on you like a crown of gold. God withholds no good thing from those He loves, and He loves you completely.' },
    { title: 'Journey with God', verse: '"Show me your ways, Lord, teach me your paths. Guide me in your truth and teach me, for you are God my Savior." - Psalm 25:4-5', message: '{{babyname}}, every day of your life is a beautiful journey with God by your side. He knows every path ahead and promises to walk every step with you. May you always invite Him into every adventure and every new day. The best journeys in life are the ones where God leads the way and you follow with a trusting heart.' },
  ],
  'K': [
    { title: 'Known by God', verse: '"O Lord, you have searched me and you know me. You know when I sit and when I rise; you perceive my thoughts from afar." - Psalm 139:1-2', message: '{{babyname}}, God knows absolutely everything about you and loves you completely. He knows your thoughts before you think them and your words before you speak them. May you always feel the comfort of being truly and fully known by Him. There is no greater feeling in all the world than being known and loved exactly as you are.' },
    { title: 'Kept in His Hands', verse: '"The Lord will watch over your coming and going both now and forevermore." - Psalm 121:8', message: '{{babyname}}, God keeps you safe in His strong and gentle hands. From the moment you wake up until you close your eyes at night, He watches over you. May you always rest easy knowing that the Lord never sleeps and never stops watching. You are kept by a God whose hands are powerful enough to hold the whole world.' },
    { title: 'Kindness Received', verse: '"Surely your goodness and love will follow me all the days of my life." - Psalm 23:6', message: '{{babyname}}, God\'s kindness follows you wherever you go like a faithful friend. His goodness and love chase after you every single day of your life. May you always recognize His kindness in the sunshine, in the flowers, and in every good thing. He is constantly pouring out His tender love on you in a hundred different ways.' },
    { title: 'Kingdom Child', verse: '"The Lord has established his throne in heaven, and his kingdom rules over all." - Psalm 103:19', message: '{{babyname}}, you belong to the greatest Kingdom that has ever existed. The King of all creation calls you His child and His own. May you always walk with the quiet confidence of someone who belongs to the Most High God. You carry His Kingdom inside you and His love goes before you everywhere you go.' },
    { title: 'Knit with Purpose', verse: '"My frame was not hidden from you when I was made in the secret place, when I was woven together in the depths of the earth." - Psalm 139:15', message: '{{babyname}}, God wove you together with purpose, love, and incredible detail. Every part of you was planned and made by His creative and caring hands. May you always marvel at how wonderfully and thoughtfully He made you. You are not an accident — you are a masterpiece carefully crafted by the greatest Creator of all.' },
  ],
  'L': [
    { title: 'Loved Completely', verse: '"How priceless is your unfailing love, O God! People take refuge in the shadow of your wings." - Psalm 36:7', message: '{{babyname}}, God\'s love for you is priceless and completely without end. It is the kind of love that never runs out no matter how many times you need it. May you always find your safe place tucked under the shadow of His wings. In His love you are completely accepted, completely valued, and completely adored.' },
    { title: 'Light of God', verse: '"The Lord is my light and my salvation; whom shall I fear? The Lord is the stronghold of my life." - Psalm 27:1', message: '{{babyname}}, God\'s light shines on you and lights up every part of your world. When things feel dark and confusing, His light always shows the way. May you carry His light inside you and share it with everyone around you. You are a child of the Light, and no darkness in this world can ever put that out.' },
    { title: 'Lifted High', verse: '"You, Lord, are a shield around me, my glory, the One who lifts my head high." - Psalm 3:3', message: '{{babyname}}, when your head feels heavy, God lifts it up with His gentle hand. He is your shield and your glory, the One who makes you feel brave again. May you always let Him lift your eyes from the ground back up to the sky. God sees the best in you even when you cannot see it yourself.' },
    { title: 'Led by His Spirit', verse: '"He refreshes my soul. He guides me along the right paths for his name\'s sake." - Psalm 23:3', message: '{{babyname}}, God refreshes your tired heart and leads you back to the right path. Like a cool drink of water on a very hot day, His Spirit revives you. May you follow His gentle leading all the days of your life. When He guides your steps, you will always find your way to the most beautiful places.' },
    { title: 'Legacy of Faith', verse: '"But from everlasting to everlasting the Lord\'s love is with those who fear him, and his righteousness with their children\'s children." - Psalm 103:17', message: '{{babyname}}, God\'s love is a gift that is passed down from generation to generation. The faith of those who love God becomes a treasure for their children and grandchildren. May you grow up to carry this beautiful legacy of love and faithfulness forward. You are part of an eternal story of God\'s goodness that will never stop being told.' },
  ],
  'M': [
    { title: 'Mighty in God', verse: '"The Lord is my strength and my shield; my heart trusts in him, and he helps me." - Psalm 28:7', message: '{{babyname}}, God is your strength and your mighty shield. When you feel too small or too weak, His power lives inside you. May you always trust that the Lord helps you with every hard thing you face. With God as your strength, you are mightier than you will ever know.' },
    { title: 'Merciful Love', verse: '"The Lord is merciful and gracious, slow to anger and abounding in steadfast love." - Psalm 103:8', message: '{{babyname}}, God\'s mercy means He is always patient, gentle, and kind with you. He never gives up on you even when you make mistakes. May you always run to Him knowing He receives you with open and loving arms. His mercy is new every single morning, a fresh and beautiful gift just for you.' },
    { title: 'Made for Glory', verse: '"The heavens declare the glory of God; the skies proclaim the work of his hands." - Psalm 19:1', message: '{{babyname}}, just like the beautiful sky declares God\'s glory, so do you. You were made to reflect the beauty and goodness of your Creator. May your life be a declaration of how wonderful and creative God truly is. Every smile you give and every kindness you show points the world back to Him.' },
    { title: 'More than Enough', verse: '"The Lord is my shepherd, I lack nothing." - Psalm 23:1', message: '{{babyname}}, with God as your shepherd you will always have everything you need. He fills your life with more than enough of His goodness and grace. May you grow up with a grateful heart that always sees how richly God provides. He takes care of you like the most devoted shepherd who loves each lamb with his whole heart.' },
    { title: 'Marked by His Love', verse: '"I will sing of the Lord\'s great love forever; with my mouth I will make your faithfulness known through all generations." - Psalm 89:1', message: '{{babyname}}, God\'s great love has left a beautiful mark on your life. His faithfulness to you is a story worth telling to everyone around you. May you grow up singing of His goodness and sharing His love with the world. You carry His mark of love on your heart, and it will shine through you all your days.' },
  ],
  'N': [
    { title: 'Never Alone', verse: '"Where can I go from your Spirit? Where can I flee from your presence?" - Psalm 139:7', message: '{{babyname}}, no matter where you go, God is always right there with you. There is no place so far or so dark that His presence cannot reach you. May you always feel the warm comfort of knowing you are never, ever alone. God fills every space around you with His love, and you are surrounded by Him always.' },
    { title: 'Nurtured by Grace', verse: '"He made us, and we are his; we are his people, the sheep of his pasture." - Psalm 100:3', message: '{{babyname}}, God made you and He takes wonderful care of everything He makes. Like a loving shepherd who tends his flock with great devotion, He nurtures you. May you always feel the warmth of belonging to someone who treasures you completely. You are His, and in His pasture you will always find everything your heart needs.' },
    { title: 'Named by God', verse: '"Before I formed you in the womb I knew you, before you were born I set you apart." - inspired by scripture, using Psalm: "You created my inmost being; you knit me together in my mother\'s womb." - Psalm 139:13', message: '{{babyname}}, God knew your name before anyone else in the world did. He thought of you, planned you, and lovingly made every part of you. May you always carry your name with pride knowing God Himself gave it meaning. You were known and loved before your very first breath, and that love has never stopped.' },
    { title: 'Nourished in Faith', verse: '"Taste and see that the Lord is good; blessed is the one who takes refuge in him." - Psalm 34:8', message: '{{babyname}}, God invites you to taste and discover just how good He truly is. The more you know Him, the more your faith grows deep and strong. May you always hunger to know God more and to experience His wonderful goodness. Like the most nourishing food for your soul, His love fills you up in the best possible way.' },
    { title: 'New Every Morning', verse: '"From the rising of the sun to the place where it sets, the name of the Lord is to be praised." - Psalm 113:3', message: '{{babyname}}, every morning God gives you a brand new day full of His goodness. From the very first ray of sunshine to the last star at night, He is worthy of praise. May you wake up each morning with a grateful and excited heart ready for His gifts. Every new day is a fresh page in the beautiful story God is writing for your life.' },
  ],
  'O': [
    { title: 'Overflowing with Blessing', verse: '"You prepare a table before me in the presence of my enemies. You anoint my head with oil; my cup overflows." - Psalm 23:5', message: '{{babyname}}, God fills your cup so full that it overflows with His goodness. His blessings pour out on you more than you can even hold. May your life be a picture of an overflowing cup — always more than enough. God loves to lavish His goodness on you because you are His treasured and beloved child.' },
    { title: 'Ordained for Greatness', verse: '"For you created my inmost being; you knit me together in my mother\'s womb. I praise you because I am fearfully and wonderfully made." - Psalm 139:13-14', message: '{{babyname}}, God ordained a great and beautiful purpose for your life before you were born. He designed you with everything you need to do the good things He planned for you. May you grow up confident in the calling God has placed on your life. You were made for something wonderful, and God will equip you for every step of the way.' },
    { title: 'Open to His Love', verse: '"Open my eyes that I may see wonderful things in your law." - Psalm 119:18', message: '{{babyname}}, God opens your eyes to see the beautiful wonders all around you. Every butterfly, every rainbow, every giggle is a gift from His loving hand. May you grow up with wide open eyes and an open heart to receive all His gifts. The world is full of His love and beauty when you learn to look for it everywhere.' },
    { title: 'On Solid Ground', verse: '"He set my feet on a rock and gave me a firm place to stand." - Psalm 40:2', message: '{{babyname}}, God places your feet on solid rock so you will never slip and fall. When everything around you feels shaky, He is your firm and steady foundation. May you always build your life on the rock of God\'s love and truth. No storm or wind can knock you down when you are standing on the promises of God.' },
    { title: 'Object of His Delight', verse: '"For the Lord takes delight in his people; he crowns the humble with victory." - Psalm 149:4', message: '{{babyname}}, you are the object of God\'s great delight and affection. He takes pleasure in every little thing you do and every smile on your face. May you always live with the joy of knowing how much God enjoys you. You are not a burden to Him — you are His delight, His treasure, and His joy.' },
  ],
  'P': [
    { title: 'Protected by His Power', verse: '"God is our refuge and strength, an ever-present help in trouble." - Psalm 46:1', message: '{{babyname}}, God is your refuge and your mighty fortress of protection. He is always close and always ready to be your strength when you need it. May you always run to Him first when things feel hard or scary. In His strong and loving arms you will always find the help and safety you need.' },
    { title: 'Praised by Heaven', verse: '"Let everything that has breath praise the Lord." - Psalm 150:6', message: '{{babyname}}, the whole created world joins together to praise the God who made you. Every bird, every flower, every star sings of His greatness and love. May you add your voice to that beautiful song of praise every single day. When you praise God with your whole heart, you join the most beautiful choir in all of creation.' },
    { title: 'Precious in His Sight', verse: '"How precious to me are your thoughts, O God! How vast is the sum of them!" - Psalm 139:17', message: '{{babyname}}, God thinks about you more times than there are grains of sand on every beach. His thoughts toward you are always full of love and wonderful plans. May you always feel the warmth of knowing how often He thinks of you. You are so precious to God that His mind is constantly filled with tender thoughts of you.' },
    { title: 'Planted by the River', verse: '"That person is like a tree planted by streams of water, which yields its fruit in season and whose leaf does not wither." - Psalm 1:3', message: '{{babyname}}, God plants you beside rivers of living water so you will always thrive. Like a strong and healthy tree, you will bear good fruit in every season of life. May your roots grow deep in His Word and His love so nothing can dry you out. When you stay close to God, you will always have everything you need to grow and flourish.' },
    { title: 'Perfected in Love', verse: '"The Lord will fulfill his purpose for me; your steadfast love, O Lord, endures forever." - Psalm 138:8', message: '{{babyname}}, God is working out His perfect purpose in your life with every passing day. His steadfast love never wavers as He shapes you into all He created you to be. May you trust His process even when you cannot see the full picture yet. He is the most patient and loving artist, and you are His most cherished work in progress.' },
  ],
  'Q': [
    { title: 'Quieted by His Love', verse: '"Be still before the Lord and wait patiently for him." - Psalm 37:7', message: '{{babyname}}, God quiets your heart and helps you find peace in the stillness. In the quiet moments with Him, He speaks the sweetest and most loving things. May you learn to be still and listen for His gentle voice in your heart. The most wonderful things God says to you come in the quiet places of trust and rest.' },
    { title: 'Quickened by His Spirit', verse: '"Create in me a pure heart, O God, and renew a steadfast spirit within me." - Psalm 51:10', message: '{{babyname}}, God\'s Spirit makes your heart new and alive every single day. Like a fresh wind that blows away everything stale and tired, He renews you. May you always let His Spirit fill you up with life and energy and joy. A heart that is quickened by God is a heart that is ready to love and live fully.' },
    { title: 'Quenched by Living Water', verse: '"As the deer pants for streams of water, so my soul pants for you, my God." - Psalm 42:1', message: '{{babyname}}, God is the living water that satisfies every thirst of your soul. Like a thirsty deer running to a cool and bubbling stream, He is exactly what you need. May you always run to Him when your heart feels empty or dry. Only God can quench the deepest thirst of your heart and fill you up completely.' },
    { title: 'Quietly Kept', verse: '"He who watches over Israel will neither slumber nor sleep. The Lord watches over you." - Psalm 121:4-5', message: '{{babyname}}, God quietly keeps watch over you every moment of every day and night. While you sleep, He never closes His eyes because He is always watching over you. May you rest in the deep peace of knowing you are never left unguarded. The One who made the stars stays awake all night just to watch over you with love.' },
    { title: 'Quickened to Praise', verse: '"I will extol the Lord at all times; his praise will always be on my lips." - Psalm 34:1', message: '{{babyname}}, God puts a song of praise in your heart that bubbles up at all times. Even in the ordinary moments of every day, He gives you reasons to be grateful. May praise become as natural to you as breathing in and breathing out. A heart that is always ready to praise God is a heart that is always full of joy.' },
  ],
  'R': [
    { title: 'Redeemed and Restored', verse: '"He heals the brokenhearted and binds up their wounds." - Psalm 147:3', message: '{{babyname}}, God is the great restorer who makes everything beautiful again. When things are broken or hurting, His loving hands gently put them back together. May you always bring every broken piece of your heart to Him for healing. He redeems every sad story and restores every hurting heart with His tender love.' },
    { title: 'Resting in His Peace', verse: '"In peace I will lie down and sleep, for you alone, Lord, make me dwell in safety." - Psalm 4:8', message: '{{babyname}}, God gives you the most peaceful and restful sleep every night. Because He is watching over you, you can close your eyes without a single worry. May your heart always find its deepest rest in the safety of His presence. The peace God gives is sweeter and deeper than anything else in all the world.' },
    { title: 'Rooted in Truth', verse: '"Your word, Lord, is eternal; it stands firm in the heavens." - Psalm 119:89', message: '{{babyname}}, God\'s Word is the most solid and trustworthy truth in all of creation. It stands firm when everything else around you shifts and changes. May you grow up with your roots planted deep in the truth of what God says about you. A life built on His eternal Word is a life that will never be swept away.' },
    { title: 'Rejoicing Always', verse: '"Sing to the Lord a new song, for he has done marvelous things." - Psalm 98:1', message: '{{babyname}}, God fills your heart with a brand new song of joy every day. His marvelous works are happening all around you all the time. May you always have eyes to see His wonders and a heart ready to celebrate. Every day with God is filled with reasons to rejoice, to sing, and to be glad.' },
    { title: 'Radiant with His Glory', verse: '"Those who look to him are radiant; their faces are never covered with shame." - Psalm 34:5', message: '{{babyname}}, when you keep your eyes on God, His glory shines right through you. Looking to Him fills your face with a radiance that the whole world can see. May you always look up to Him especially when the days feel long and hard. God\'s light shining on you makes you glow with a beauty that comes from deep inside.' },
  ],
  'S': [
    { title: 'Sheltered by God', verse: '"He will cover you with his feathers, and under his wings you will find refuge; his faithfulness will be your shield and rampart." - Psalm 91:4', message: '{{babyname}}, God shelters you under His wings like the most caring and protective parent. His faithfulness wraps around you like a shield that nothing can get through. May you always run to Him when the storms of life begin to blow. Under His wings you will find the safest, warmest, and most loving shelter of all.' },
    { title: 'Sustained by His Hand', verse: '"Cast your cares on the Lord and he will sustain you; he will never let the righteous be shaken." - Psalm 55:22', message: '{{babyname}}, God sustains you and keeps you steady through every single season. When your arms get tired from carrying too much, He takes the weight from you. May you always cast every worry and every burden into His strong and capable hands. He will hold you up and keep you going because His love for you never runs dry.' },
    { title: 'Secure in His Love', verse: '"I keep my eyes always on the Lord. With him at my right hand, I will not be shaken." - Psalm 16:8', message: '{{babyname}}, keeping your eyes on God is the secret to staying steady and secure. With Him at your right hand there is nothing that can truly shake you. May you grow up building your security on the unshakeable foundation of His love. No matter what changes around you, God\'s love for you is the one thing that stays perfectly the same.' },
    { title: 'Singing His Praise', verse: '"I will sing to the Lord all my life; I will sing praise to my God as long as I live." - Psalm 104:33', message: '{{babyname}}, God puts a song in your heart that lasts your whole lifetime. From your very first breath to your very last, He is worthy of all your songs. May your life be one long beautiful melody of praise and gratitude to Him. A heart that sings to God is a heart that has discovered the greatest joy of all.' },
    { title: 'Strengthened Daily', verse: '"The Lord gives strength to his people; the Lord blesses his people with peace." - Psalm 29:11', message: '{{babyname}}, God gives you fresh strength every single morning that you wake up. Along with His strength comes His deep and beautiful peace that fills your heart. May you begin each day by asking Him to fill you up with all you need. He is faithful to make you strong enough for whatever the day may bring to you.' },
  ],
  'T': [
    { title: 'Treasured by God', verse: '"How precious to me are your thoughts, God! How vast is the sum of them! Were I to count them, they would outnumber the grains of sand." - Psalm 139:17-18', message: '{{babyname}}, you are more treasured by God than you could ever fully understand. His thoughts of you are as countless as every grain of sand on every beach in the world. May you always feel the wonder of being so deeply and constantly thought of. You are God\'s most precious treasure and He never stops thinking about you with love.' },
    { title: 'Touched by His Grace', verse: '"Blessed is the one whose transgressions are forgiven, whose sins are covered." - Psalm 32:1', message: '{{babyname}}, God\'s grace touches your life and covers you with His forgiveness. He wipes the slate clean and gives you a fresh and beautiful start. May you always receive His grace with a grateful and humble heart. There is nothing you could ever do that is bigger than His love and His grace for you.' },
    { title: 'Trusting in Him', verse: '"Trust in the Lord and do good; dwell in the land and enjoy safe pasture." - Psalm 37:3', message: '{{babyname}}, trusting God is the very best thing you can do with your whole heart. When you put your trust in Him, He leads you to the greenest and safest places. May you grow up choosing to trust His plan even when you do not understand it. A heart that trusts God is a heart that will always find its way to good and peaceful places.' },
    { title: 'Transformed by Love', verse: '"Create in me a pure heart, O God, and renew a steadfast spirit within me." - Psalm 51:10', message: '{{babyname}}, God transforms your heart and makes it new and clean and beautiful. He takes what is old and worn and renews it with His powerful and gentle love. May you always let Him work in your heart and shape you into something wonderful. The most beautiful transformation in all the world is what God does when love gets inside a heart.' },
    { title: 'Tenderly Cared For', verse: '"The Lord is good to all; he has compassion on all he has made." - Psalm 145:9', message: '{{babyname}}, God tends to you with the most tender and compassionate care. He is good to everything He has made, and He made you with the greatest love. May you always feel His gentle compassion surrounding you like the softest light. No one in all the world cares for you as tenderly and as faithfully as God does.' },
  ],
  'U': [
    { title: 'Uplifted by Grace', verse: '"The Lord upholds all who fall and lifts up all who are bowed down." - Psalm 145:14', message: '{{babyname}}, when you stumble or fall, God is right there to lift you back up. He reaches down with His gentle hand and sets you on your feet again. May you never be afraid to fall because you know who is always there to catch you. God\'s grace is the most powerful uplifting force in all the world, and it is all for you.' },
    { title: 'Unshakeable in Faith', verse: '"God is our refuge and strength, an ever-present help in trouble. Therefore we will not fear." - Psalm 46:1-2', message: '{{babyname}}, with God as your refuge you have nothing in this world to fear. His strength inside you makes you unshakeable even in the biggest storms. May you grow up rooted so deeply in Him that nothing can move you from His love. The faith that is built on God is the most unshakeable and solid thing there is.' },
    { title: 'Under His Wings', verse: '"He will cover you with his feathers, and under his wings you will find refuge." - Psalm 91:4', message: '{{babyname}}, you have the most beautiful place of safety waiting for you always. Under God\'s wings you are warm, protected, and surrounded by His love. May you always run to that sheltered place when the world feels big and scary. There is no safer or sweeter place than tucked under the wings of your Heavenly Father.' },
    { title: 'Upheld by His Right Hand', verse: '"I am always with you; you hold me by my right hand. You guide me with your counsel." - Psalm 73:23-24', message: '{{babyname}}, God holds your right hand and walks every step of life with you. He is your counselor and guide, always leading you in the best direction. May you feel the firm and loving grip of His hand in yours every single day. No matter what you face, His hand is right there holding yours and never letting go.' },
    { title: 'Understood by God', verse: '"Before a word is on my tongue you, Lord, know it completely." - Psalm 139:4', message: '{{babyname}}, God understands you better than anyone else in the whole world. He knows every word before you say it and every feeling before you express it. May you always feel the deep comfort of being completely known and understood. You never have to explain yourself to God because He already knows and already loves every part of you.' },
  ],
  'V': [
    { title: 'Victorious in God', verse: '"With your help I can advance against a troop; with my God I can scale a wall." - Psalm 18:29', message: '{{babyname}}, with God by your side you can overcome any obstacle that comes your way. He makes you brave enough and strong enough to climb every wall and face every giant. May you always step into your challenges knowing that God goes before you. Victory is yours not because of your own strength but because of the mighty God who fights for you.' },
    { title: 'Valued by Heaven', verse: '"The Lord redeems his servants; no one who takes refuge in him will be condemned." - Psalm 34:22', message: '{{babyname}}, Heaven places the highest possible value on your precious life. You are redeemed and cherished by the God who created every star in the sky. May you always know that you are worth everything to your Heavenly Father. No price was too high for God to pay to show you just how much you mean to Him.' },
    { title: 'Vessel of His Glory', verse: '"The heavens declare the glory of God; the skies proclaim the work of his hands." - Psalm 19:1', message: '{{babyname}}, just like the sky displays the glory of God, so do you. You are a vessel that carries His beauty, His love, and His light into the world. May your life declare to everyone around you how wonderful God truly is. Every act of kindness, every smile of joy, every word of love is God\'s glory shining through you.' },
    { title: 'Vibrant in His Love', verse: '"My heart is glad and my tongue rejoices; my body also will rest secure." - Psalm 16:9', message: '{{babyname}}, God fills you with a vibrant joy that spills out of your whole being. His love makes your heart glad and your mouth full of songs and laughter. May you always be full of life and energy that comes from knowing how loved you are. A heart that is loved by God is one of the most vibrant and alive things in all the world.' },
    { title: 'Vindicated by Love', verse: '"The Lord will vindicate his people and have compassion on his servants." - Psalm 135:14', message: '{{babyname}}, God always stands up for those He loves and fights for their cause. He has compassion on you and cares deeply about everything that concerns you. May you always trust that God sees every injustice and every hurt you experience. He is your defender and your champion, and His love always has the final word in your story.' },
  ],
  'W': [
    { title: 'Wrapped in His Love', verse: '"How priceless is your unfailing love, O God! People take refuge in the shadow of your wings." - Psalm 36:7', message: '{{babyname}}, God wraps you in His love like the warmest and most beautiful blanket. His unfailing love surrounds you and keeps you safe in every season. May you always crawl under the shadow of His wings when you need comfort. There is nothing more priceless in all the world than the love God has wrapped around your life.' },
    { title: 'Watched Over Always', verse: '"He will not let your foot slip — he who watches over you will not slumber." - Psalm 121:3', message: '{{babyname}}, God watches over every step you take so your feet will never slip. He never gets tired and He never falls asleep because He is always on guard for you. May you walk with confidence knowing the most powerful Protector is watching over you. Every step you take is safe because God\'s eyes are lovingly following you always.' },
    { title: 'Wondrous Creation', verse: '"I praise you because I am fearfully and wonderfully made; your works are wonderful, I know that full well." - Psalm 139:14', message: '{{babyname}}, you are one of God\'s most wonderful and beautiful creations. He made you with such careful and loving attention to every little detail. May you always look in the mirror and see what God sees — something truly wonderful. You are His workmanship, His masterpiece, and He is so very proud of how He made you.' },
    { title: 'Walking in His Ways', verse: '"Blessed are all who fear the Lord, who walk in obedience to him." - Psalm 128:1', message: '{{babyname}}, walking in God\'s ways is the most blessed and beautiful way to live. When you follow His path, He leads you to green pastures and still waters. May you grow up choosing His ways over and over again with a willing heart. The life that walks closely with God is a life that overflows with blessing from the inside out.' },
    { title: 'Worthy in His Eyes', verse: '"For the Lord takes delight in his people; he crowns the humble with victory." - Psalm 149:4', message: '{{babyname}}, in God\'s eyes you are completely and utterly worthy of His love. He crowns you with His blessing and delights in every little thing about you. May you always believe in your own worth because it is God Himself who declares it. You do not have to earn His love because He has already decided that you are worth everything to Him.' },
  ],
  'X': [
    { title: 'eXtraordinary Love', verse: '"How great is the love the Father has lavished on us." - inspired, using Psalm: "Your love, Lord, reaches to the heavens, your faithfulness to the skies." - Psalm 36:5', message: '{{babyname}}, God\'s love for you is truly extraordinary and beyond all understanding. It reaches higher than the sky and stretches wider than the whole horizon. May you spend your whole life discovering just how extraordinary His love truly is. Every day reveals a new and wonderful dimension of the love God has for you.' },
    { title: 'eXalted Child', verse: '"He raises the poor from the dust and lifts the needy from the ash heap; he seats them with princes." - Psalm 113:7-8', message: '{{babyname}}, God lifts you up and seats you among royalty because you are His child. He takes the humble and the small and makes them great in His Kingdom. May you always carry yourself with the dignity of one who belongs to the Most High God. You are not just ordinary — you are exalted and elevated by the love of your Heavenly Father.' },
    { title: 'eXceptional Design', verse: '"I praise you because I am fearfully and wonderfully made; your works are wonderful, I know that full well." - Psalm 139:14', message: '{{babyname}}, God designed you with exceptional care and incredible attention to detail. Every single part of you was planned and crafted by the most creative hands in the universe. May you always celebrate how uniquely and beautifully God put you together. You are not like anyone else because God made you as an exceptional and one-of-a-kind creation.' },
    { title: 'eXquisite Grace', verse: '"The Lord is gracious and righteous; our God is full of compassion." - Psalm 116:5', message: '{{babyname}}, God pours out His exquisite grace on you with compassion and tenderness. His grace is not plain or ordinary — it is the most beautiful and refined gift of all. May you always receive His grace with a heart that marvels at His goodness. Every day you are wrapped in the exquisite grace of a God who loves you beyond all measure.' },
    { title: 'eXpressive Worship', verse: '"Shout for joy to the Lord, all the earth, burst into jubilant song with music." - Psalm 98:4', message: '{{babyname}}, God delights in the expressive and joyful worship of those who love Him. He made music and laughter and dancing all as beautiful ways to praise His name. May your life be full of expressive and jubilant worship that comes from a grateful heart. When you praise God with everything you have, you bring Him the greatest joy.' },
  ],
  'Y': [
    { title: 'Yielded to His Plan', verse: '"In their hearts humans plan their course, but the Lord establishes their steps." - inspired, using Psalm: "The Lord makes firm the steps of the one who delights in him." - Psalm 37:23', message: '{{babyname}}, God has a wonderful plan for your life that is better than anything you could dream up. When you yield your heart to Him, He establishes your steps and makes your path straight. May you grow up trusting His plan even when it takes unexpected and surprising turns. The steps God orders for you are always leading somewhere more beautiful than you can imagine.' },
    { title: 'Your God is Near', verse: '"The Lord is near to all who call on him, to all who call on him in truth." - Psalm 145:18', message: '{{babyname}}, your God is never far away — He is closer than your very next breath. All you have to do is call out to Him and He is right there beside you. May you always remember that God hears every word you speak to Him with love. He draws near to those who draw near to Him, and He is always just a prayer away.' },
    { title: 'Your Strength and Song', verse: '"The Lord is my strength and my defense; he has become my salvation." - Psalm 118:14', message: '{{babyname}}, God is your strength when you are weak and your song when you have no words. He fills you up with power and with music when your own supply runs out. May you always turn to Him as your source of strength and your reason to sing. With God as your strength and your song, every day becomes a new and beautiful melody.' },
    { title: 'You Are His', verse: '"Know that the Lord is God. It is he who made us, and we are his; we are his people, the sheep of his pasture." - Psalm 100:3', message: '{{babyname}}, the most wonderful truth in all the world is that you belong to God. He made you and He claims you as His very own precious child. May you always carry with you the deep peace and security of knowing whose you are. You are His — completely, permanently, and joyfully — and nothing can ever change that beautiful truth.' },
    { title: 'Years of Blessing', verse: '"Surely your goodness and love will follow me all the days of my life, and I will dwell in the house of the Lord forever." - Psalm 23:6', message: '{{babyname}}, God\'s goodness and love will follow you through every single year of your life. From your very first year to your very last, His blessing will never stop chasing after you. May you look back at the end of each year and count the countless ways He showed up for you. God is the faithful companion of every season, and His blessing never runs out.' },
  ],
  'Z': [
    { title: 'Zeal for God', verse: '"My soul yearns, even faints, for the courts of the Lord; my heart and my flesh cry out for the living God." - Psalm 84:2', message: '{{babyname}}, God loves a heart that burns with zeal and passion for His presence. When your soul longs for Him the way it longs for nothing else, you will find Him. May you grow up with a zeal for God that never cools or grows tired. A heart that is on fire for God is one of the most beautiful and powerful things in all the world.' },
    { title: 'Zion\'s Child', verse: '"Great is the Lord, and most worthy of praise, in the city of our God, his holy mountain." - Psalm 48:1', message: '{{babyname}}, you belong to the city of the Great King and you are a child of Zion. The God who is worshipped on His holy mountain calls you by name and claims you as His own. May you always walk with the quiet confidence of one who belongs to the Most High. You are a child of the King\'s own city, and His greatness and glory surround your life.' },
    { title: 'Zealous in Love', verse: '"I love you, Lord, my strength." - Psalm 18:1', message: '{{babyname}}, God wants your love to be as wholehearted and zealous as His love for you. He loves you with all of His strength and all of His being every single day. May you grow up loving Him back with the same passionate and wholehearted devotion. When you love God with everything you have, you discover that He is your greatest strength of all.' },
    { title: 'Zeal of His House', verse: '"How lovely is your dwelling place, Lord Almighty! Better is one day in your courts than a thousand elsewhere." - Psalm 84:1,10', message: '{{babyname}}, God\'s presence is the most lovely and wonderful place you could ever be. One single day close to Him is better than a thousand days anywhere else in the world. May you grow up with a deep love for God\'s house and His wonderful presence. The zeal for being near to God is one of the greatest gifts He can place inside a heart.' },
    { title: 'Zealous Hope', verse: '"I wait for the Lord, my whole being waits, and in his word I put my hope." - Psalm 130:5', message: '{{babyname}}, God gives you a hope that makes waiting feel full of beautiful expectation. When you wait for Him with a zealous and trusting heart, He always comes through. May you grow up putting all your hope in His Word and in His faithful promises. A heart that hopes zealously in God is a heart that will never, ever be disappointed.' },
  ],
};

